                an = depot_xy if p == len(ri) - 1 else coords[ri[p + 1]]
                rem_i = dist(ap, an) - dist(ap, coords[a]) - dist(coords[a], an)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if loads[j] + demands[a] > cap:
                        continue
                    rj = routes[j]
                    for pos in range(len(rj) + 1):
                        l = depot_xy if pos == 0 else coords[rj[pos - 1]]
                        r = depot_xy if pos == len(rj) else coords[rj[pos]]
                        add = dist(l, coords[a]) + dist(coords[a], r) - dist(l, r)
                        delta = rem_i + add
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best = (i, p, j, pos, a)
        if best is not None:
            i, p, j, pos, a = best
            routes[i].pop(p)
            if i == j and pos > p:
                pos -= 1
            routes[j].insert(pos, a)
            routes = [r for r in routes if r]
            routes = [two_opt(r) for r in routes]
            changed = True

    seen = {}
    for r in routes:
        for cid in r:
            seen[cid] = seen.get(cid, 0) + 1

    missing = [cid for cid in custs if cid not in seen]
    if missing:
        pool = []
        used = {}
        for r in routes:
            for cid in r:
                if cid not in used:
                    pool.append(cid)
                    used[cid] = 1
        for cid in missing:
            pool.append(cid)
        pool = sorted(pool, key=ang_key)
        routes = []
        cur = []
        rem = cap
        for cid in pool:
            d = demands[cid]
            if d <= rem:
                cur.append(cid)
                rem -= d
            else:
                if cur:
                    routes.append(cur)
                cur = [cid]
                rem = cap - d
        if cur:
            routes.append(cur)

    final = []
    for r in routes:
        if r:
            final.append(r)
    return final
